module TopModule (
    input  logic [99:0] in,
    output logic [99:0] out_both,
    output logic [99:0] out_any,
    output logic [99:0] out_different
);

    always_comb begin
        // out_both: in[i] and in[i+1]
        for (int i = 0; i < 99; i++) begin
            out_both[i] = in[i] & in[i+1];
        end
        out_both[99] = 1'b0;

        // out_any: in[i] or in[i-1]
        out_any[0] = 1'b0;
        for (int i = 1; i < 100; i++) begin
            out_any[i] = in[i] | in[i-1];
        end

        // out_different: in[i] ^ in[i+1], with wrap-around at 99
        for (int i = 0; i < 99; i++) begin
            out_different[i] = in[i] ^ in[i+1];
        end
        out_different[99] = in[99] ^ in[0];
    end

endmodule

module TopModule (
    input  logic [99:0] in,
    output logic [99:0] out_both,
    output logic [99:0] out_any,
    output logic [99:0] out_different
);

    assign out_both      = {1'b0, in[98:0] & in[99:1]};
    assign out_any       = {in[99:1] | in[98:0], 1'b0};
    assign out_different = {in[99] ^ in[0], in[98:0] ^ in[99:1]};

endmodule

module tb_TopModule;

    logic [99:0] in;
    logic [99:0] out_both;
    logic [99:0] out_any;
    logic [99:0] out_different;

    TopModule dut (
        .in(in),
        .out_both(out_both),
        .out_any(out_any),
        .out_different(out_different)
    );

    initial begin
        // Test case 1: All zeros
        in = 100'h0;
        #1;
        if (out_both !== 100'h0 || out_any !== 100'h0 || out_different !== 100'h0) begin
            $display("SELFTEST FAIL: All zeros test failed. got both=%h, any=%h, diff=%h", out_both, out_any, out_different);
            $finish;
        end

        // Test case 2: All ones
        in = {100{1'b1}};
        #1;
        // out_both: [99]=0, [98:0]=1
        // out_any: [99:1]=1, [0]=0
        // out_different: all 0
        if (out_both !== {1'b0, 99'h7FFFFFFFFFFFFFFFFFFFFFFFF}) begin
            $display("SELFTEST FAIL: All ones out_both failed: %h", out_both);
            $finish;
        end
        if (out_any !== {99'h7FFFFFFFFFFFFFFFFFFFFFFFF, 1'b0}) begin
            $display("SELFTEST FAIL: All ones out_any failed: %h", out_any);
            $finish;
        end
        if (out_different !== 100'h0) begin
            $display("SELFTEST FAIL: All ones out_different failed: %h", out_different);
            $finish;
        end

        // Test case 3: Alternating 1010...
        in = 100'h5555555555555555555555555; // 5 is 0101
        #1;
        // Check manually or via golden model
        // Let's write a simple golden model check inside tb
        for (int i = 0; i < 100; i++) begin
            logic exp_both, exp_any, exp_diff;
            if (i == 99) exp_both = 1'b0;
            else exp_both = in[i] & in[i+1];

            if (i == 0) exp_any = 1'b0;
            else exp_any = in[i] | in[i-1];

            if (i == 99) exp_diff = in[99] ^ in[0];
            else exp_diff = in[i] ^ in[i+1];

            if (out_both[i] !== exp_both || out_any[i] !== exp_any || out_different[i] !== exp_diff) begin
                $display("SELFTEST FAIL: Random/Alt pattern mismatch at index %0d. exp(b/a/d)=%b/%b/%b got=%b/%b/%b", 
                         i, exp_both, exp_any, exp_diff, out_both[i], out_any[i], out_different[i]);
                $finish;
            end
        end

        // Test case 4: Random patterns
        for (int t = 0; t < 20; t++) begin
            in = $random | ($random << 32) | ($random << 64);
            #1;
            for (int i = 0; i < 100; i++) begin
                logic exp_both, exp_any, exp_diff;
                if (i == 99) exp_both = 1'b0;
                else exp_both = in[i] & in[i+1];

                if (i == 0) exp_any = 1'b0;
                else exp_any = in[i] | in[i-1];

                if (i == 99) exp_diff = in[99] ^ in[0];
                else exp_diff = in[i] ^ in[i+1];

                if (out_both[i] !== exp_both || out_any[i] !== exp_any || out_different[i] !== exp_diff) begin
                    $display("SELFTEST FAIL: Random pattern %0d mismatch at index %0d. in=%h", t, i, in);
                    $finish;
                end
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
